getFiltersWhere(filters: FiltersDto) {
  const whereFilters: Record<string, unknown> = {};
  if (filters.category)
    whereFilters['categories'] = { name: { equals: filters.category } };
  if (filters.department)
    whereFilters['owner_department'] = filters.department;
  if (filters.min_cost !== undefined && filters.max_cost !== undefined) {
    whereFilters['AND'] = [
      { monthly_cost: { lte: filters.max_cost } },
      { monthly_cost: { gte: filters.min_cost } }
    ]
  }

export class CreateToolDto {
  @IsString()
  @Length(2, 100)
  @IsNotEmpty()
  name: string;

  @IsOptional()
  @IsString()
  description?: string;

  @IsString()
  @Length(1, 100)
  @IsNotEmpty()
  vendor: string;

  @IsUrl()
  @IsOptional()
  website_url?: string;

  @IsEnum(tools_owner_department)
  @IsNotEmpty()
  owner_department: tools_owner_department;

  @IsNumber({ maxDecimalPlaces: 2 })
  @IsNotEmpty()
  @Min(0)
  monthly_cost: number;

  @IsNumber()
  @IsNotEmpty()
  @Min(1)
  category_id: number;
}

